export type PrepColor = "blue" | "purple" | "teal" | "amber" | "green" | "coral" | "gray";

export interface PrepCard {
  title: string;
  body: string;
  cue?: string;
  color?: PrepColor;
}

export interface StarStory {
  title: string;
  useFor: string;
  situation: string;
  task: string;
  action: string;
  result: string;
  pmFrame: string;
}

export interface InterviewQuestion {
  question: string;
  audience: string;
  answer: string;
  cue: string;
}

export interface InterviewStage {
  stage: string;
  format: string;
  focus: string;
  status: "Complete" | "Upcoming";
}

export interface AnchorRoute {
  question: string;
  primary: string;
  backup: string;
  proof: string;
}

export interface ReadinessDimension {
  id: string;
  label: string;
  description: string;
}

